PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE builtin(
  -- The name as its place holds it: a native value's key, a role's word, an
  -- atom or a former as a source spells it, or a member as `<Head>.<member>`,
  -- or bare when no head holds it.
  name      TEXT NOT NULL CONSTRAINT "name is a word, a key with dots, or a head and a member" CHECK(name <> '' AND name NOT GLOB '*[^A-Za-z0-9_.+]*'),
  -- The source that holds the name: the one table of `gandr-core-term`, or a
  -- place that a later unit moves into it.
  place     TEXT NOT NULL CONSTRAINT "place is a source of a crate" CHECK(place GLOB 'crates/*/src/*.rs' AND place NOT GLOB '*[^A-Za-z0-9_/.-]*'),
  -- What the name is: a native value, a type atom, a type former, a member of
  -- a former, or a role that a former of the core reads.
  kind      TEXT NOT NULL CONSTRAINT "kind is value, atom, former, member or role" CHECK(kind IN ('value', 'atom', 'former', 'member', 'role')),
  -- Who gives the meaning: the toolchain for a given name, the library for a
  -- found one.
  direction TEXT NOT NULL CONSTRAINT "direction is given or found" CHECK(direction IN ('given', 'found')),
  -- Who states the type: a signature of its declaration, or the elaborator
  -- for a form whose type no signature states.
  signature TEXT NOT NULL CONSTRAINT "signature is stated or elaborator" CHECK(signature IN ('stated', 'elaborator')),
  PRIMARY KEY(name, place)
) WITHOUT ROWID;
COMMIT;
